const b = cuboid(40,40,20)
round(b, 4)
const c = cylinder(10,40,{at:[0,0,0]})
join(b, c)

const c = cylinder(24,30)
round(c, 3)
const k = cuboid(10,10,40,{at:[0,0,0]})
subtract(c, k)

const sk = sketch('top')
sk.rect(20,10)
const p = pull(sk, 8)
round(p, 1)

const sk = sketch('front')
sk.rect(10,20,{at:[20,0]})
const p = spin(sk, 360)
round(p, 1)

const b = cuboid(40,40,20)
const c = cylinder(10,40,{at:[0,0,0]})
